# Let's define the bipartite graph and verify it's triangle-free and maximal
A = [0,1,2,3,6,9,11,14]
B = [4,5,7,8,10,12,13,15,16]

edges = set()
for a in A:
    for b in B:
        u, v = sorted((a,b))
        edges.add((u,v))

print(f"Number of edges: {len(edges)}")

# Check triangle-free
vertices = list(range(17))
adj = {v: set() for v in vertices}
for u,v in edges:
    adj[u].add(v)
    adj[v].add(u)

triangles = []
for u in vertices:
    for v in adj[u]:
        if v > u:
            for w in adj[v]:
                if w > v and w in adj[u]:
                    triangles.append((u,v,w))
print(f"Triangles found: {len(triangles)}")

# Check maximality: for every non-edge, there is a common neighbor
non_edges = []
for u in range(17):
    for v in range(u+1, 17):
        if (u,v) not in edges:
            non_edges.append((u,v))

print(f"Number of non-edges: {len(non_edges)}")

maximal = True
for u,v in non_edges:
    common = adj[u] & adj[v]
    if len(common) == 0:
        print(f"Non-edge ({u},{v}) has no common neighbor! Not maximal.")
        maximal = False
        break

print(f"Is maximal: {maximal}")

# Check required edges
required = [(0,15),(3,15),(6,15),(9,15),(11,15),(14,16)]
for e in required:
    if e not in edges:
        print(f"Missing required edge: {e}")
    else:
        print(f"Required edge {e} present")

# Print edges sorted
edge_list = sorted(edges)
print("\nEdge list:")
for e in edge_list:
    print(e)
